class Interval:
    def __init__(self, start: date, end: date) -> None:
        self.start, self.end = start, end

    @classmethod
    def from_iso(cls, text: str) -> "Interval":
        start, end = (date.fromisoformat(p) for p in text.split("/"))
        return cls(start, end)      # subclasses get their own type back

class Shape(ABC):
    registry: ClassVar[dict[str, type[Shape]]] = {}

    def __init_subclass__(cls, **kwargs: object) -> None:
        super().__init_subclass__(**kwargs)
        Shape.registry[cls.__name__.lower()] = cls

    @abstractmethod
    def draw(self) -> None: ...

def make_shape(kind: str, size: float) -> Shape:
    return Shape.registry[kind](size)
